function() {
  const textarea = document.querySelector('textarea[aria-label="WolframAlpha input field"]');
  if (textarea) {
    // Find the form or submit button
    const form = textarea.closest('form');
    if (form) {
      form.submit();
      return 'Form submitted';
    }
    // Try to find a submit button sibling
    const submitBtn = document.querySelector('button[aria-label="Compute input button"]');
    if (submitBtn) {
      submitBtn.click();
      return 'Submit button clicked';
    }
    return 'No form or button found';
  }
  return 'No textarea found';
}

() => {
  const textarea = document.querySelector('textarea[aria-label="WolframAlpha input field"]');
  if (textarea) {
    const form = textarea.closest('form');
    if (form) {
      form.submit();
      return 'Form submitted';
    }
    const submitBtn = document.querySelector('button[aria-label="Compute input button"]');
    if (submitBtn) {
      submitBtn.click();
      return 'Submit button clicked';
    }
    return 'No form or button found';
  }
  return 'No textarea found';
}

() => {
  const submitBtn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.trim() === 'Compute');
  if (submitBtn) {
    submitBtn.click();
    return 'Compute button clicked';
  }
  return 'No compute button found';
}

() => {
  const submitBtns = Array.from(document.querySelectorAll('button[type="submit"]'));
  const result = submitBtns.map(b => ({text: b.textContent.trim(), ariaLabel: b.getAttribute('aria-label')}));
  return JSON.stringify(result);
}

() => {
  const allBtns = document.querySelectorAll('button');
  const result = [];
  allBtns.forEach((b, i) => {
    if (b.textContent.trim().includes('Compute')) {
      result.push({index: i, text: b.textContent.trim(), type: b.type, aria: b.getAttribute('aria-label')});
    }
  });
  return JSON.stringify(result);
}

() => {
  const ta = document.querySelector('textarea[aria-label="WolframAlpha input field"]');
  if (ta) {
    ta.focus();
    return ta.value;
  }
  return 'not found';
}
